"""Finalize actual negative study outcomes without replacing a deployed model or PPT."""
import json,hashlib,datetime,re,zipfile,collections
from pathlib import Path
import xml.etree.ElementTree as ET
import requests
ROOT=Path(__file__).resolve().parents[1]
def read(p):return json.loads(p.read_text(encoding='utf-8'))
def digest(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(p,x):p.write_text(json.dumps(x,indent=2),encoding='utf-8')
def main():
 names=['pure_capacity_20261108','pure_capacity_bn_20261108','pure_residual_capacity_20261108','pure_native_rollback_20261109','pure_fine_head_20261109'];runs=[ROOT/'reports'/n for n in names];decisions={n:read(p/'deployment_decision.json') for n,p in zip(names,runs)};assert all(not d['eligible'] and not d['test_evaluated'] for d in decisions.values())
 expected=read(runs[-1]/'protected_artifacts.json');protected={n:digest(ROOT/n)==h for n,h in expected.items()};assert all(protected.values());originals=read(ROOT/'reports/source_audit.json')['files'];assert all(digest(ROOT/'external/raag-ratnakar-main'/f['path'])==f['sha256'] for f in originals)
 ppt=ROOT/'output/RagaMoodSync_Research.pptx'
 with zipfile.ZipFile(ppt) as z:slides=[n for n in z.namelist() if re.fullmatch(r'ppt/slides/slide\d+\.xml',n)];assert len(slides)==13 and z.testzip() is None
 current=read(ROOT/'reports/emotion_evaluation.json');c=current['classification_report'];assert current['n']==6561 and sum(a==b for a,b in zip(current['predictions']['truth'],current['predictions']['predicted']))/current['n']==current['accuracy'];modelsha=digest(ROOT/'models/fusdense.pt');assert modelsha==current['checkpoint_sha256']
 health=requests.get('http://127.0.0.1:8000/api/health',timeout=20);health.raise_for_status();live=requests.get('http://127.0.0.1:8000/api/research/results',timeout=30);live.raise_for_status();assert live.json()['checkpoint']['sha256']==modelsha
 suites=ET.parse(ROOT/'reports/capacity_final_tests.xml').getroot();nodes=[suites] if suites.tag=='testsuite' else list(suites);tests={k:sum(float(s.get(k,0)) for s in nodes) for k in ['tests','failures','errors','skipped','time']};assert tests['tests']==104 and tests['failures']==tests['errors']==0
 coarse=read(runs[2]/'fixed_checkpoint_generalization_audit.json');fine=read(runs[4]/'fixed_checkpoint_generalization_audit.json');changes=read(runs[2]/'final_parameter_update_audit.json');head_count=len(read(runs[0]/'head_history.json'))+len(read(runs[4]/'head_history.json'));full_count=len(read(runs[0]/'full_history.json'))+len(read(runs[2]/'full_history.json'));now=datetime.datetime.now().astimezone().isoformat()
 lines=['# RagaMoodSync overfitting study: actual final results','',now,'', '**Outcome: the requested performance improvement was not achieved.** No candidate met every validation requirement, no new full-test candidate was evaluated, and the app/model/PPT remain unchanged. Failed candidates were not installed.','',f"The study completed **{head_count}classifier-only trial epochs** and **{full_count}full-network epochs**. They are different workloads, not{head_count+full_count}full-network epochs. The four compact-head recipes include a one-epoch timing-limited run, explicitly retained and reported. TRAIN has23,503source faces, including330disgust faces versus6,039happy faces; augmented views are not new subjects.",'','## Best verified deployed PURE model','',f"All{current['n']}retained test faces: **accuracy{current['accuracy']:.2%}; macroF1{c['macro avg']['f1-score']:.4f}**. Disgust precision{c['disgust']['precision']:.4f}, recall{c['disgust']['recall']:.2%}(37/79),F1{c['disgust']['f1-score']:.4f}. These are unchanged previously measured results, not a new test result from this study.",'','| Class | Actual deployed test recall | Support |','|---|---:|---:|']
 for name in ['angry','disgust','fear','happy','sad','surprise','neutral']:lines.append(f"| {name} | {c[name]['recall']:.2%} | {int(c[name]['support'])} |")
 lines+=['','## Fixed-checkpoint overfitting measurements','', 'All23,503original TRAIN images and3,970validation images; eval mode, no dropout, augmentation, confidence filtering or label changes. Fine-model cached features are valid because its entire backbone is bit-identical to the verified source. These are in-sample TRAIN scores, not new generalization evidence.','', '| Diagnostic model | Parameters | TRAIN accuracy | Validation accuracy | TRAIN minus validation |','|---|---:|---:|---:|---:|',f"| Verified deployed model |1,828,896|{coarse['baseline_train']['accuracy']:.2%}|{coarse['baseline_validation']['accuracy']:.2%}|{coarse['accuracy_gap_before']:.2%}|",f"| Final compact residual model, rejected |589,456|{coarse['candidate_train']['accuracy']:.2%}|{coarse['candidate_validation']['accuracy']:.2%}|{coarse['accuracy_gap_after']:.2%}|",f"| Fine-spatial384head diagnostic, rejected |1,408,544|{fine['candidate_train']['accuracy']:.2%}|{fine['candidate_validation']['accuracy']:.2%}|{fine['accuracy_gap_after']:.2%}|",'', 'The aggressive model reduced the gap by reducing fitting ability, without improving validation quality. The milder classifier still overfits. Neither observation establishes a successful fix. Parameter count alone is not the sole explanation; the current feature/training/data combination still lacks the required generalization. These joint trials are not causal ablations, and label-noise or identity effects are not established here.','', '## What actually changed and what failed','', '- Native spatial capacity control:3276to1260features and128/256heads;4independent head recipes followed by6full-network passes. Fine spatial information/capacity was reduced, but aggregate/class requirements were not met. Details:PURE_CAPACITY_RESULTS.md.','- Native residual-dense feature learning: six zero-output residual refinements, two dilated growth layers each, GroupNorm,117,360new feature parameters,4additional full-network passes. Real64face initial-function check had0logit error. '+str(changes['changed_emotion_path_tensors'])+'emotion-path parameter tensors changed, including'+str(changes['changed_native_refinement_tensors'])+'new refinement tensors. This proves learning updates, not a performance improvement. Details:PURE_RESIDUAL_CAPACITY_RESULTS.md.','- TRAIN-only BatchNorm recalibration:3fixed candidates, parameters unchanged. It did not improve quality. One compact candidate had52%validation disgust recall but only15.76%precision, and was rejected. Modest mean-statistic drift did not support a major BN defect. Details:PURE_BATCHNORM_RESULTS.md.','- Native parameter rollback:4predeclared validation checks within one network. Restoring older feature parameters broke co-adapted representations; examples had78%disgust recall with4.18%precision, or80%precision with16%recall. None qualified. These are validation metrics, not high overall accuracy.','- Milder native classifier control:512to384units, all3276fine spatial/fusion features retained, class-balanced TRAIN neuron ranking and omitted-activation mean compensation;20classifier-only epochs. Starts from the verified active pure model, not failed full-network weights. Fixed TRAINaccuracy93.19%versus58.41%validation shows overfitting remains.','- Timing fix: very long wall-clock pauses prematurely cut one classifier recipe. The subsequent full phases used process CPU/4with minimum completed epochs and fixed maximum passes. Source before/after and declarations are preserved; no metric gate changed.','', '## Integrity and limitations','', 'Every class and error remains included. No external encoder, probability mixture, test-label fitting, post-test threshold or fabricated metric was used. Same-current-pure TRAIN references were used only during training; they are discarded for inference. The test budget was never used because no validation candidate qualified. The fixed test was historically inspected and validation repeatedly reused; there is no fresh subject-disjoint or webcam-domain confirmation.','',f"Final software suite: **{int(tests['tests'])}passed**,0failures,0errors,15dependency warnings; pytest reported129.71seconds (XML{tests['time']:.3f}). Original{len(originals)}repository files remain byte-identical. All8protected files and the13-slide PowerPoint are unchanged. Live health/research endpoints match the deployed checkpoint SHA.",'', 'EEG/HRV/weather/raga-efficacy results are unchanged. This study makes no new sensor, synchronized physiological-fusion, clinical-benefit or80%accuracy claim.','', 'Re-run software checks:','', '```powershell',r'.\.venv\Scripts\python.exe -m pytest -q','```','', 'Completed experiment directories preserve protocols, exact executed sources, every validation report, histories, checkpoints and explicit non-deployment decisions. Their completed/frozen data are not overwritten for further training.']
 (ROOT/'OVERFITTING_STUDY_RESULTS.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
 backup=ROOT/'reports/capacity_final_document_backups';backup.mkdir(exist_ok=False)
 for name in ['PROJECT_STATUS.md','EXPERIMENTS.md']: (backup/name).write_bytes((ROOT/name).read_bytes())
 summary=f"# Completed overfitting study - 9 November 2026\n\nRequested model-performance improvement remains UNACHIEVED. Completed{head_count}classifier-only trial epochs and{full_count}full-network epochs,3TRAIN-only BN checks and4native parameter-rollback checks. None met every unchanged class/aggregate validation gate; no new full-test candidate was evaluated. App/model/PPT remain byte-identical at58.34%testaccuracy,0.5554macroF1,46.84%disgustrecall.\n\nFixed-checkpoint results: original TRAIN92.08%/validation58.41%(gap33.66pp); compact residual TRAIN72.52%/validation58.01%(gap14.51pp), showing loss of fitting ability without improved validation; fine-spatial384head TRAIN93.19%/validation58.41%(gap34.78pp), still overfitting. No80%, reliable-webcam or new physiology/weather/raga efficacy result is claimed.\n\nFinal104software tests passed,15dependency warnings,129.71seconds. All55original repository files unchanged; all8protected files unchanged; PowerPoint remains13slides. Live app SHA matchesf0082aff0511c40d8dff89fc03bbea965b416db55a0f771701efaa38f490c548. Full actual findings:OVERFITTING_STUDY_RESULTS.md; detailed phases:PURE_CAPACITY_RESULTS.md,PURE_BATCHNORM_RESULTS.md,PURE_RESIDUAL_CAPACITY_RESULTS.md.\n\nEarlier records follow.\n\n"
 for name in ['PROJECT_STATUS.md','EXPERIMENTS.md']:
  p=ROOT/name;p.write_text(summary+p.read_text(encoding='utf-8'),encoding='utf-8')
 result={'completed_at':now,'performance_goal_achieved':False,'tests':tests,'original_files_unchanged':len(originals),'protected_unchanged':protected,'ppt_slides':len(slides),'model_sha256':modelsha,'ppt_sha256':digest(ppt),'live_app_matches':True,'new_test_evaluated':False,'classifier_trial_epochs':head_count,'full_network_epochs':full_count,'decisions':decisions};write(ROOT/'reports/capacity_study_final_audit.json',result)
 for run in runs:write(run/'completion.json',{'reported':True,'performance_goal_achieved':False,'app_model_ppt_unchanged':True,'decision':read(run/'deployment_decision.json')})
 print(json.dumps({k:v for k,v in result.items() if k not in ['decisions','protected_unchanged']},indent=2))
if __name__=='__main__':main()
